package com.example.pricelist.data

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase

@Database(
    entities = [ItemEntity::class, ItemFts::class], // include FTS entity
    version = 1,
    exportSchema = false
)
abstract class AppDatabase : RoomDatabase() {
    abstract fun itemDao(): ItemDao

    companion object {
        @Volatile private var INSTANCE: AppDatabase? = null

        fun getInstance(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "price_list.db"
                ).fallbackToDestructiveMigration()
                 .build()
                 .also { INSTANCE = it }
            }
        }
    }
}

package com.example.pricelist.data

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase

@Database(
    entities = [ItemEntity::class, ItemFts::class], // include FTS entity
    // Bumped DB version to include new `TaxPercent` column
    version = 2,
    exportSchema = false
)
abstract class AppDatabase : RoomDatabase() {
    abstract fun itemDao(): ItemDao

    companion object {
        @Volatile private var INSTANCE: AppDatabase? = null

        fun getInstance(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "price_list.db"
                ).fallbackToDestructiveMigration()
                 .build()
                 .also { INSTANCE = it }
            }
        }
    }
}

package com.example.pricelist.data
import androidx.room.Entity import androidx.room.PrimaryKey
@Entity(tableName = "items") data class ItemEntity( val Code: String = "", val DiscPercent: Double = 0.0, val MRP: Double = 0.0, @PrimaryKey val MasterCode: String = "", val Name: String = "", val PRICE3: Double = 0.0, val Unit: String = "", val imageExt: String = "", val imageH: Int = 0, val imageW: Int = 0, val imageYes: Boolean = false, val lastFBUpdate: Long = 0L
)

